// Generated by `bun run build:web` (scripts/build-web.mjs); the CLI build runs
// it first whenever the WEB_UI feature is on.
import manifest from '../../web/dist/assets.json'
import type { WebAsset } from './webServer.js'

type ManifestEntry = { type: string; text?: string; base64?: string }

export function loadWebAssets(): Map<string, WebAsset> {
  const assets = new Map<string, WebAsset>()
  for (const [path, entry] of Object.entries(
    manifest as Record<string, ManifestEntry>,
  )) {
    assets.set(path, {
      type: entry.type,
      body: entry.text ?? Buffer.from(entry.base64 ?? '', 'base64'),
    })
  }
  return assets
}
